Given a binary tree, a target node in the binary tree, and an integer value k, the task is to find all the nodes at a distance k from the given target node. No parent pointers are available.Note:You have to return the list in sorted order.The tree will not contain duplicate values.Examples:Input: target = 2, k = 2Output: 3Explanation: Nodes at a distance 2 from the given target node 2 is 3.Input: target = 3, k = 1 Output: 1 6 7 Explanation: Nodes at a distance 1 from the given target node 3 are 1 , 6 & 7.Try It YourselfTable of Content[Expected Approach - 1] Using Recursion - O(nlogn) Time and O(h) Space[Expected Approach - 2] Using Depth First Search with parent pointers - O(nlogn) Time and O(n) Space[Expected Approach - 1] Using Recursion - O(nlogn) Time and O(h) SpaceThe idea is to traverse the binary tree using recursion and find the target node. Find all the nodes in the left and right subtree of target node that are at a distance k. Also for all the nodes in the path of target node, find all the nodes in the opposite subtree that are at the distance of  (k - distance of target node).Below is the implementation of the above approach:
            C++

    // C++ program to find nodes
// at distance k from target.
#include <bits/stdc++.h>
using namespace std;

class Node {
  public:
    int data;
    Node *left, *right;
    Node(int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Function which finds the nodes at a given
// distance from root node
void findNodes(Node *root, int dis, vector<int> &ans) {

    // base case
    if (root == nullptr)
        return;

    if (dis == 0) {
        ans.push_back(root->data);
        return;
    }

    findNodes(root->left, dis - 1, ans);
    findNodes(root->right, dis - 1, ans);
}

// Function which returns the distance of a node
// target node. Returns -1 if target is not found.
int kDistanceRecur(Node *root, int target, int k, vector<int> &ans) {

    // base case
    if (root == nullptr)
        return -1;

    // If current node is target
    if (root->data == target) {

        // Find nodes at distance k from
        // target node in subtree.
        findNodes(root, k, ans);

        return 1;
    }

    int left = kDistanceRecur(root->left, target, k, ans);

    // If target node is found in left
    // subtree, find all nodes at distance
    // k-left in right subtree.
    if (left != -1) {
        if (k - left == 0)
            ans.push_back(root->data);
        else
            findNodes(root->right, k - left - 1, ans);
        return left + 1;
    }

    int right = kDistanceRecur(root->right, target, k, ans);

    // If target node is found in right
    // subtree, find all nodes at distance
    // k-right in left subtree.
    if (right != -1) {
        if (k - right == 0)
            ans.push_back(root->data);
        else
            findNodes(root->left, k - right - 1, ans);
        return right + 1;
    }

    // If target node is not found
    // return -1
    return -1;
}

vector<int> KDistanceNodes(Node *root, int target, int k) {
    vector<int> ans;

    kDistanceRecur(root, target, k, ans);

    // sort the result
    sort(ans.begin(), ans.end());

    return ans;
}

void printList(vector<int> v) {
    int n = v.size();
    for (int i = 0; i < n; i++) {
        cout << v[i] << " ";
    }
    cout << endl;
}

int main() {

    // Create a hard coded tree.
    //         20
    //       /    \
    //      7      24
    //    /   \
    //   4     3
    //        /
    //       1
    Node *root = new Node(20);
    root->left = new Node(7);
    root->right = new Node(24);
    root->left->left = new Node(4);
    root->left->right = new Node(3);
    root->left->right->left = new Node(1);

    int target = 7, k = 2;
    vector<int> ans = KDistanceNodes(root, target, k);

    printList(ans);
    return 0;
}


